SELECT m.id,m.winner,m.loser,m.winner_rank,m.loser_rank,m.round,m.score,e.date,e.name event,e.surface,e.type,pw.name winner_name,pl.name loser_name FROM matches m JOIN events e ON e.id=m.event JOIN players pw ON pw.id=m.winner JOIN players pl ON pl.id=m.loser WHERE (m.winner IN ('V812','C0BH') OR m.loser IN ('V812','C0BH')) AND m.status IN ('Completed','Aborted') AND e.date BETWEEN '2025-10-20' AND '2026-10-19'